# Install klte UCM (new files only). Reversible: rm -r the two paths below.
set -e
U=/usr/share/alsa/ucm2
mkdir -p $U/Samsung/klte
echo 'U3ludGF4IDQKClNlY3Rpb25Vc2VDYXNlLiJIaUZpIiB7CglGaWxlICIvU2Ftc3VuZy9rbHRlL0hpRmkuY29uZiIKCUNvbW1lbnQgIlBsYXkgSGlGaSBxdWFsaXR5IE11c2ljIgp9Cg==' | base64 -d > $U/Samsung/klte/klte.conf
echo '' | base64 -d > $U/Samsung/klte/HiFi.conf
mkdir -p "$U/conf.d/Samsung_Galaxy_"
ln -sf ../../Samsung/klte/klte.conf "$U/conf.d/Samsung_Galaxy_/Samsung Galaxy S5.conf"
mkdir -p "$U/conf.d/msm8974"
ln -sf ../../Samsung/klte/klte.conf "$U/conf.d/msm8974/Samsung Galaxy S5.conf"
ls -la $U/Samsung/klte "$U/conf.d/Samsung_Galaxy_" "$U/conf.d/msm8974"
alsaucm -c hw:0 list _verbs 2>&1 | head; alsaucm -c hw:0 set _verb HiFi list _devices 2>&1 | head
